// navigateBridge (#3274, epic #3260) — the PURE half of `bsc navigate`: resolve a request into store
// mutations and report the view that landed.
//
// Split from `useNavigateBridge.ts` so the decisions (what a request resolves to, what is an error, what
// the resulting view is) are unit-testable without Tauri or a rendered app. The hook is a thin adapter.
//
// CONTRACT
// - A request is INTENTS, not steps: `component` implies its workspace + page. A caller asking for a
//   component should not need to know which Workspace hosts the Design Studio this week.
// - Unknown ids are ERRORS, not silent no-ops. A capture against a view that never landed is exactly the
//   failure this surface exists to prevent, so "I couldn't" must be louder than "sure".
// - The ack reports what ACTUALLY landed — RE-READ from the store after applying, never echoed from the
//   request and never read off a pre-mutation snapshot (zustand hands out a new object per update, so a
//   captured `getState()` goes stale the moment you set anything). An ack that reports the view you asked
//   for rather than the one you got would defeat the whole surface: the caller would capture confidently
//   against the wrong screen.
import type { AppStore } from "@/store/types";
import type { Workspace } from "@/app/registry";
import { dispatchPage } from "@/app/navigate";
import { blanketDismissable, refuseDismissal } from "@/app/chrome/banners";

/** The `--dismiss` value that clears every non-decision notice. */
const ALL_NOTICES = "all";

/** The preview DATA-STATES `--state` navigates to (#3717) — the navigable subset of the Design Studio's
 *  state axis (`error` is a render OUTCOME, not something you request). Kept in lockstep with the Rust
 *  `NAV_STATES` in `bsc-navigate`'s CLI. `as const` so the values narrow to a union assignable to the
 *  store's `PreviewState` without a cross-feature type import. */
const NAV_STATES = ["loaded", "empty", "loading"] as const;

/** What `bsc navigate` asks for. Every field optional; absent ⇒ leave it alone. Mirrors Rust `NavRequest`. */
export interface NavRequest {
  /** A human asked for this steer, so the presence gate does not apply (#4248). */
  force?: boolean;
  workspace?: string;
  page?: string;
  kit?: string;
  component?: string;
  theme?: string;
  state?: string;
  /** #54 — clear an app NOTICE (a banner id, or `all`). Banners dismiss through local React state, so a
   *  session driving the app from a shell could see one in a capture and had no way to clear it. */
  dismiss?: string;
}

/** What we send back to Rust. Mirrors Rust `NavAck`. */
export interface NavAck {
  id?: string;
  error?: string;
  /** INTERNAL, never sent to Rust — the adapter strips it (#navigate-answers-from-a-stale-app-snapshot).
   *
   *  Set when the error is a miss that a RE-READ could plausibly fix: this resolves against the app's
   *  hydrated copy of the store, and an external `bsc ui set` only reaches that copy while the Design
   *  Studio is visible (`useUiActivity` is mounted there and gated on it). So a session writing a
   *  component from a shell, with the app showing Console, gets "unknown component" for a record that
   *  demonstrably exists — request #55.
   *
   *  This function stays PURE, so it only says the miss is retryable; `useNavigateBridge` owns the
   *  async hydrate and the single retry. */
  retryAfterHydrate?: boolean;
  /** Set when a `component` intent focused the record but did NOT switch the view (#3599/#4248).
   *
   *  Without it the ack reports the CURRENT view and reads as an ordinary success — so a caller that
   *  asked for a component, saw `workspace: "github"` come back, and had nothing to photograph concluded
   *  the navigate had failed and forced the view with `navigate page designs`. That escalation, fired
   *  every ~7s by the designer loop, IS the yank. Saying "declined, and why" is what makes the refusal
   *  legible instead of looking like a bug to route around. */
  declined?: string;
  /** INTERNAL, never sent to Rust — the adapter strips it after using it.
   *
   *  The component id whose preview frame is expected to REBUILD because of this navigate. Set only when
   *  the Studio is actually the visible page, so a declined or human-blocked navigate never waits for a
   *  mount that will not happen.
   *
   *  This module stays PURE: it says what to wait for, and `useNavigateBridge` owns the bounded wait and
   *  fills in `mounted`/`mountError`. Deliberately NOT a buildability check here — re-deriving that
   *  predicate is exactly how the doctor and the preview came to disagree. The frame registry reports
   *  what actually happened, including failures the predicate cannot see (a bundle that threw). */
  awaitMount?: string;

  /** What the preview frame is actually SHOWING once it settled. Absent when nothing was expected to
   *  mount, or when the frame did not settle inside the budget — `mountError` then says which. */
  mounted?: string;
  /** Why the selected component is not on screen. */
  mountError?: string;
  /** #54 — the notices this request actually cleared. Reported so `dismiss all` is auditable rather than
   *  a silent sweep, and so a caller can tell "nothing was showing" from "it worked". */
  dismissed?: string[];

  workspace?: string;
  page?: string;
  kit?: string;
  component?: string;
  theme?: string;
  state?: string;
}

/** The vocabulary the resolver validates against.
 *
 *  `read` is a LIVE getter, not a snapshot — see the contract note above. Passed in so this module stays
 *  pure and testable with a fake store. */
export interface NavVocab {
  /** Is a human at the keyboard right now (#4248)? Injected rather than imported so this module stays
   *  pure and a test can drive both worlds. Defaults to "nobody is here" when omitted, which keeps every
   *  existing caller (and the unattended loop) behaving exactly as before. */
  humanPresent?: () => boolean;
  read: () => AppStore;
  workspaces: Workspace[];
  /**
   * The valid page ids for a workspace, or `null` when the shell cannot know them
   * (`navigation-vocabulary-follows-the-new-page-structure`).
   *
   * It was a FLAT `pages: string[]` holding the Planner's modes, and every workspace's page was checked
   * against that one list — so a legitimate `bsc navigate page rust` on Algorithms would have been
   * refused for not being a Planner tab. Per-workspace is the fix.
   *
   * `null` means PERMISSIVE, and that is deliberate rather than a gap. Several graphs derive their tabs
   * from data the shell does not hold — the languages present in the knowledge graph, the sound kits,
   * the languages the data entities are written in — and inventing a hard-coded list for those would go
   * stale silently, which is worse than not checking. Nothing is lost by allowing them: `usePageTabs`
   * heals an id that names no tab, and the ack reports the page that ACTUALLY landed, so a typo comes
   * back as a visible mismatch rather than as a false success.
   */
  pagesFor: (w: Workspace) => string[] | null;
}

/** The Workspace hosting the Design Studio, and the page within it. Resolved here (not by the caller) so
 *  `bsc navigate component` keeps working if the Studio moves. */
const DESIGNS_WORKSPACE: Workspace = "components";

/**
 * The page a workspace is CURRENTLY on — what the ack reports.
 *
 * It read `s.projectsPageMode` unconditionally, so every ack reported the Planner's page whatever
 * workspace you were on. That was invisible while the Planner hosted every page; now that the graphs
 * are their own workspaces it would answer `bsc navigate page rust` with `page: "projects"` — a
 * confident lie, and the ack exists precisely so a caller can trust what landed.
 *
 * Each workspace's page lives where that workspace keeps it: a dedicated field for the older screens,
 * `activePageTab` for the tabbed ones, and for Components the technology of the ACTIVE KIT, since its
 * tab is derived rather than stored. `console` has no string page at all — its tabs are index-switched.
 */
function pageOf(s: AppStore, w: Workspace): string | undefined {
  switch (w) {
    case "settings": return s.settingsSection;
    case "console": return undefined;
    case "components": {
      const kit = s.kits.find((k) => k.id === s.designsKitId) ?? s.kits[0];
      return kit ? ((kit.tech ?? "").trim().toLowerCase() || "other") : undefined;
    }
    default: return s.activePageTab[w];
  }
}

/** How many candidate ids an error may name. The app kit carries ~476 components and a miss used to print
 *  EVERY id in it — a wall a terminal reader scrolls past, with the one line that mattered at the top of
 *  it. A bounded set plus a count of what was not printed says the same thing and can be read. */
const MAX_SUGGESTIONS = 8;

/** A component as this resolver needs to see it. Structural rather than the store's `ComponentRecord`, so
 *  a fixture can be three fields wide and the lite projection (which carries no `name`) still resolves by
 *  id. */
type NavComponent = { id: string; kitId: string; name?: string };

/** Ids that LOOK like `handle` — the "did you mean" set. Substring in either direction, case-insensitively.
 *
 *  Deliberately NOT an edit distance. Every miss actually filed against this surface was an AFFIX away —
 *  the store id carries a folder prefix (`settings-`, `teams-`) that nothing on screen shows — and a
 *  distance metric answers those worse while inventing confident neighbours for a genuine typo. */
function nearMisses(pool: NavComponent[], handle: string): string[] {
  const h = handle.toLowerCase();
  const like = (v: string): boolean => !!v && (v.includes(h) || h.includes(v));
  return pool
    .filter((c) => like(c.id.toLowerCase()) || like((c.name ?? "").toLowerCase()))
    .map((c) => c.id)
    .sort()
    .slice(0, MAX_SUGGESTIONS);
}

/**
 * The component a request names, or a STATED error — never an exception, and never a silent pick.
 *
 * Resolves an id first, then a unique `name` case-insensitively: the same tolerance `bsc ui get` has had
 * since designer request #91 (`resolve_component_handle` in `bsc-component`), adopted here because the
 * INCONSISTENCY between the two was itself filed twice. Request #104 reported "KeyboardCard's preview
 * hangs the app" because `bsc navigate component base-studio-code keyboardcard` timed out; the record is
 * `settings-keyboardcard`, name `KeyboardCard`, which `bsc ui get` accepts and this resolver did not. The
 * session went looking at that card's keyboard listeners — its effect is guarded on `capturingId`, so
 * there was never anything there to find — then filed the same symptom a second time for `formlane`, id
 * `teams-form-lane`, name `FormLane`. Two false bug reports out of one lookup gap is the argument for
 * closing it.
 *
 * An AMBIGUOUS name is REFUSED naming the candidates, exactly as `resolve_component_handle` refuses one:
 * resolving to whichever sorts first is how the next false report gets filed.
 */
function resolveComponentHandle(
  components: NavComponent[],
  kitId: string,
  handle: string,
): { comp: NavComponent } | { error: string; retryAfterHydrate?: boolean } {
  if (!kitId) {
    return {
      error: `unknown component '${handle}' — name a kit: bsc navigate component <kit> ${handle}`,
      retryAfterHydrate: true,
    };
  }
  const inKit = components.filter((c) => c.kitId === kitId);
  const byId = inKit.find((c) => c.id === handle);
  if (byId) return { comp: byId };

  const byName = inKit.filter((c) => (c.name ?? "").toLowerCase() === handle.toLowerCase());
  if (byName.length === 1) return { comp: byName[0] };
  if (byName.length > 1) {
    // NOT retryable: a hydrate cannot make an ambiguous name unique, so spending the retry budget on it
    // would only delay an error the caller can already act on.
    return {
      error:
        `'${handle}' is the NAME of ${byName.length} components in kit '${kitId}', not an id — ` +
        `pass one of: ${byName.map((c) => c.id).sort().join(", ")}`,
    };
  }

  // A genuine miss. Name the id that failed and give the next step, in order of usefulness: the same
  // handle living in ANOTHER kit, then the ids that look like it, then a bounded sample of the kit.
  const here = `unknown component '${handle}' in kit '${kitId}'`;
  const elsewhere = components.find(
    (c) => c.kitId !== kitId && (c.id === handle || (c.name ?? "").toLowerCase() === handle.toLowerCase()),
  );
  if (elsewhere) {
    return {
      error:
        `${here} — it is in kit '${elsewhere.kitId}': ` +
        `bsc navigate component ${elsewhere.kitId} ${elsewhere.id}`,
      retryAfterHydrate: true,
    };
  }
  const near = nearMisses(inKit, handle);
  if (near.length) return { error: `${here} — did you mean: ${near.join(", ")}?`, retryAfterHydrate: true };
  if (!inKit.length) return { error: `${here} (the kit has no components)`, retryAfterHydrate: true };

  const sample = inKit.map((c) => c.id).sort().slice(0, MAX_SUGGESTIONS);
  const rest = inKit.length - sample.length;
  return {
    error:
      `${here} — ${inKit.length} component(s) there, e.g. ${sample.join(", ")}` +
      `${rest > 0 ? ` (+${rest} more; \`bsc ui list --raw\` prints them all)` : ""}`,
    retryAfterHydrate: true,
  };
}

/**
 * Apply `req` and return the ack. Never throws for a *bad request* — an unknown id becomes `error`,
 * because the caller needs a reason it can act on, not an exception.
 */
export function applyNavigate(req: NavRequest, vocab: NavVocab): NavAck {
  const { read, workspaces, pagesFor } = vocab;
  const s = read();
  // #3599: was the Design Studio ALREADY on screen before this navigate? A designer follow-along focus
  // (`bsc navigate component`, fired before each `bsc shot preview`) must not YANK the user off whatever
  // page they're on — so the component intent below only folds to the Studio when it's already showing.
  // The Studio is its own WORKSPACE now (`five-graphs-become-rail-workspaces`), so being on it is the
  // whole condition — there is no page mode to also match. Left as `projects`/`designs` this was false
  // forever, which would have quietly disabled the follow-along guard: every `bsc navigate component`
  // would have read as "the Studio is not showing" and declined to fold, and the designer loop would
  // have gone back to forcing the page every few seconds — the exact yank #4248 removed.
  const wasShowingStudio = s.activeWorkspace === DESIGNS_WORKSPACE;

  // ── Validate EVERYTHING before mutating anything ──────────────────────────────────────────────
  // A half-applied navigation is worse than a refused one: the caller gets an error AND a view that
  // partially moved, so the next capture is wrong in a way nothing reported. Validate, then commit.
  if (req.workspace !== undefined && !workspaces.includes(req.workspace as Workspace)) {
    return { error: `unknown workspace '${req.workspace}' — one of: ${workspaces.join(", ")}` };
  }
  if (req.page !== undefined) {
    // Validate against the TARGET workspace's vocabulary — the one being navigated to when the request
    // names one, else the one already showing. A flat list checked every workspace against the
    // Planner's pages, which is why a real Algorithms language would have been refused.
    const target = (req.workspace as Workspace | undefined) ?? s.activeWorkspace;
    const valid = pagesFor(target);
    if (valid && !valid.includes(req.page)) {
      return { error: `unknown page '${req.page}' for ${target} — one of: ${valid.join(", ")}` };
    }
  }
  if (req.kit !== undefined && !s.kits.some((k) => k.id === req.kit)) {
    return { error: `unknown kit '${req.kit}' — one of: ${s.kits.map((k) => k.id).join(", ")}`, retryAfterHydrate: true };
  }
  if (req.theme !== undefined && !s.kitThemes.some((t) => t.id === req.theme)) {
    return { error: `unknown theme '${req.theme}' — one of: ${s.kitThemes.map((t) => t.id).join(", ")}` };
  }
  if (req.state !== undefined && !(NAV_STATES as readonly string[]).includes(req.state)) {
    return { error: `unknown state '${req.state}' — one of: ${NAV_STATES.join(", ")}` };
  }
  // #54 — validated with the rest, BEFORE anything mutates: a half-applied navigation that also refused
  // a dismissal would leave the caller guessing which half happened.
  if (req.dismiss !== undefined && req.dismiss !== ALL_NOTICES) {
    const refusal = refuseDismissal(req.dismiss);
    if (refusal) return { error: refusal };
  }
  // A component is only meaningful inside a kit: resolve against the requested kit, else the current one.
  // Naming a component without a kit is ambiguous the moment two kits share a component name.
  let comp: { id: string; kitId: string } | undefined;
  if (req.component !== undefined) {
    const hit = resolveComponentHandle(s.components, req.kit ?? s.designsKitId ?? "", req.component);
    if ("error" in hit) return { error: hit.error, retryAfterHydrate: hit.retryAfterHydrate };
    comp = hit.comp;
  }

  // ── Commit ────────────────────────────────────────────────────────────────────────────────────
  // A blanket dismiss clears everything that does not ASK something. `session-recovery` ("restore or
  // discard?") is excluded by the registry: hiding it does not answer it, it removes the only place the
  // answer can be given, and those sessions stay unrestored with nothing on screen to say so.
  const dismissed: string[] = [];
  if (req.dismiss !== undefined) {
    for (const id of req.dismiss === ALL_NOTICES ? blanketDismissable() : [req.dismiss]) {
      s.dismissNotice(id);
      dismissed.push(id);
    }
  }
  if (req.theme !== undefined) s.setKitTheme(req.theme);
  // The preview DATA-STATE the Studio renders (#3717) — drives the same store value the state control
  // sets, so a `--state` navigate captures the intended render. Validated above, so the cast is sound.
  if (req.state !== undefined) s.setDesignsPreviewState(req.state as (typeof NAV_STATES)[number]);
  // #4248: a view change is REFUSED while a person is using the app. #3599 gated only the `component`
  // intent and honoured an explicit `--workspace`/`--page` as "a deliberate steer" — but an agent's
  // background loop is made of explicit commands, so that line separated nothing. The designer simply
  // followed its declined `navigate component` with `navigate page designs`, every ~7s.
  //
  // Presence is the line that does separate them: steering is right unattended (the overnight loop this
  // was built for) and wrong when someone is working. `--force` remains for a human driving the app from
  // their own terminal — explicit, and visible in the ack.
  const steering = req.workspace !== undefined || req.page !== undefined;
  const blockedByHuman = steering && !req.force && (vocab.humanPresent?.() ?? false);
  if (blockedByHuman) {
    // The focus still lands, so the Studio shows the right component the moment the user opens it —
    // the same shape #3599 chose. Only the VIEW is left alone.
    if (comp) {
      s.setDesignsKit(comp.kitId);
      s.setDesignsComp(comp.id);
    } else if (req.kit !== undefined) {
      s.setDesignsKit(req.kit);
    }
    if (req.theme !== undefined) s.setKitTheme(req.theme);
    return landed(
      read,
      "view unchanged: someone is using the app right now, and a background steer does not take the " +
        "screen from them (#4248). The focus is set, so it is there when they open the Studio. Pass " +
        "--force only for a steer a HUMAN asked for.",
    );
  }
  if (req.workspace !== undefined) s.setWorkspace(req.workspace as Workspace);
  // Dispatch the page through the SAME per-workspace mechanism the UI uses (#3602) instead of hard-coding
  // one workspace's setter. A page with no named workspace targets the CURRENTLY ACTIVE one — read BEFORE
  // any mutation above, so it is never stale — matching both the CLI's own help ("switch the page within
  // the current workspace") and the validation just above, which already checks a bare page against
  // `s.activeWorkspace`. This used to fall back to `DESIGNS_WORKSPACE` instead (request #164): the
  // validation passed against whatever workspace you were actually on, and the commit silently landed on
  // Components regardless — `bsc navigate page network-finance` while on Glance moved Components' page and
  // left Glance untouched, with no error reported.
  if (req.page !== undefined) dispatchPage(s, (req.workspace as Workspace) ?? s.activeWorkspace, req.page);

  // `component` implies its workspace + page — the intent is "show me this", not "set a field". But
  // (#3599) a designer follow-along must not steal the user's current page: only SWITCH to the Studio
  // when it's already showing, or when the request EXPLICITLY asked for a workspace/page (a deliberate
  // steer, not a background focus). Off-Studio, we still set the focus so it's there when the user opens
  // the Studio themselves — their current view is untouched.
  let declined: string | undefined;
  let awaitMount: string | undefined;
  if (comp) {
    if (wasShowingStudio || req.workspace !== undefined || req.page !== undefined) {
      // The Studio is a WORKSPACE now, so showing it is one call. It used to also need a page mode,
      // because it was a Planner tab.
      s.setWorkspace(DESIGNS_WORKSPACE);
      // The Studio is the visible page, so its frame WILL rebuild for this selection. Anywhere else,
      // nothing rebuilds and waiting would only burn the caller's ack budget.
      awaitMount = comp.id;
    } else {
      // The #3599 refusal, stated (#4248). It is deliberate, so it must not read as a failure.
      declined =
        "focus set, view unchanged: the Design Studio is not the visible page and a background " +
        "follow-along does not steal the user's view (#3599). Nothing is on screen to capture. Do not " +
        "force it with `navigate page` while someone is working.";
    }
    // setDesignsKit CLEARS the component (a component belongs to one kit), so the kit must come first.
    s.setDesignsKit(comp.kitId);
    s.setDesignsComp(comp.id);
  } else if (req.kit !== undefined) {
    s.setDesignsKit(req.kit);
  }

  return landed(read, declined, awaitMount, dismissed);
}

/** Read the resulting view back OUT of the store — a FRESH read, never the pre-mutation snapshot. */
function landed(read: () => AppStore, declined?: string, awaitMount?: string, dismissed?: string[]): NavAck {
  const s = read();
  return {
    awaitMount,
    dismissed: dismissed && dismissed.length > 0 ? dismissed : undefined,
    workspace: s.activeWorkspace,
    page: pageOf(s, s.activeWorkspace),
    kit: s.designsKitId || undefined,
    component: s.designsCompId ?? undefined,
    theme: s.kitTheme || undefined,
    state: s.designsPreviewState || undefined,
    declined,
  };
}
